package dev.industrialtechnology.test;
import java.util.*;import cpw.mods.fml.common.Loader;import dev.industrialtechnology.core.ModRegistry;import dev.industrialtechnology.capacitor.TileCapacitorBank;import dev.industrialtechnology.railway.*;import net.minecraft.world.*;import net.minecraft.item.*;import net.minecraft.init.Blocks;import net.minecraft.block.Block;import net.minecraftforge.common.util.*;
public final class RailPipeChecks {
 private static final List<TileRailStation> stations=new ArrayList<>();private static final List<EntityRollingStock> trains=new ArrayList<>();
 private static void track(WorldServer w,int x,int z){w.setBlock(x,70,z,RailwayRegistry.anchor,0,3);TileTrack t=(TileTrack)w.getTileEntity(x,70,z);t.facing=0;t.markDirty();TrackWorld.remove(t);TrackWorld.add(t);}
 public static void setup(WorldServer w)throws Exception{stations.clear();trains.clear();if(!Loader.isModLoaded("ThermalDynamics"))return;FakePlayer p=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RailPipeTest")){@Override public void sendPlayerAbilities(){}};p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);for(int route=0;route<(Loader.isModLoaded("EnderIO")?2:1);route++){int x=240+route*96,z=128;for(int dx=-16;dx<=64;dx+=16){w.getChunkFromChunkCoords((x+dx)>>4,z>>4);track(w,x+dx,z);}w.getChunkFromChunkCoords(x>>4,(z+3)>>4);w.setBlock(x,70,z+3,ModRegistry.capacitorBank,0,3);TileCapacitorBank bank=(TileCapacitorBank)w.getTileEntity(x,70,z+3);bank.setSide(5,1);w.setBlock(x,71,z+3,RailwayRegistry.solar[4],0,3);w.setBlock(x+4,70,z+3,RailwayRegistry.stations[0],0,3);TileRailStation station=(TileRailStation)w.getTileEntity(x+4,70,z+3);stations.add(station);TileTrack t=(TileTrack)w.getTileEntity(x,70,z);EntityRollingStock e=new EntityRollingStock(w,StockType.ACS64,new TrackWorld.Cursor(t.id,0,4,1),null);w.spawnEntityInWorld(e);trains.add(e);
 if(route==0){Object duct=Class.forName("cofh.thermaldynamics.duct.TDDucts").getField("energyResonant").get(null);ItemStack item=(ItemStack)duct.getClass().getField("itemStack").get(duct);p.setPosition(x,70,z+6);for(int i=1;i<=3;i++){w.setBlock(x+i,69,z+3,Blocks.stone);if(!item.copy().tryPlaceItemIntoWorld(p,w,x+i,69,z+3,1,.5f,1,.5f))throw new AssertionError("fluxduct placement");}}
 else{Class<?> conduit=Class.forName("crazypants.enderio.conduit.power.PowerConduit"),iface=Class.forName("crazypants.enderio.conduit.IConduit"),cm=Class.forName("crazypants.enderio.conduit.ConnectionMode"),rs=Class.forName("crazypants.enderio.machine.RedstoneControlMode");Block bundle=(Block)Class.forName("crazypants.enderio.EnderIO").getField("blockConduitBundle").get(null);for(int i=1;i<=3;i++){w.setBlock(x+i,70,z+3,bundle,0,3);Object tile=w.getTileEntity(x+i,70,z+3),power=conduit.getConstructor(int.class).newInstance(2);tile.getClass().getMethod("addConduit",iface).invoke(tile,power);if(i==1){conduit.getMethod("setConnectionMode",ForgeDirection.class,cm).invoke(power,ForgeDirection.WEST,cm.getField("INPUT").get(null));conduit.getMethod("setExtractionRedstoneMode",rs,ForgeDirection.class).invoke(power,rs.getField("IGNORE").get(null),ForgeDirection.WEST);}if(i==3)conduit.getMethod("setConnectionMode",ForgeDirection.class,cm).invoke(power,ForgeDirection.EAST,cm.getField("OUTPUT").get(null));}}
 }}
 public static void verify(java.util.function.Consumer<String> pass){for(int i=0;i<stations.size();i++){TileRailStation s=stations.get(i);EntityRollingStock e=trains.get(i);if(s.transferred<=0||e.energy<=0)throw new AssertionError("solar/cable/charging route "+i+" RF="+e.energy+" transferred="+s.transferred);pass.accept((i==0?"Thermal Dynamics fluxduct":"Ender IO conduit")+" carries actual solar RF through a capacitor and charging station into an electric locomotive");}}
}
